using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

Console.WriteLine("Research Agent Starting...");

// Validate API key
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY");
if (string.IsNullOrWhiteSpace(apiKey))
{
    Console.Error.WriteLine("Error: OPENAI_API_KEY environment variable is not set.");
    Console.Error.WriteLine("Please set it with: export OPENAI_API_KEY=your-key-here");
    return;
}

const string modelId = "gpt-4o-mini-2024-07-18";

// Build the IChatClient via OpenAI provider
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsChatClient();

// Create tool instances
var noteTaker = new NoteTaker();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.SearchWebAsync),
    AIFunctionFactory.Create(noteTaker.SaveNote),
    AIFunctionFactory.Create(noteTaker.GetNotes),
};

// Prompt user for a research topic
Console.Write("\nEnter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.Error.WriteLine("Error: No topic provided.");
    return;
}

// Create the agent with tools and instructions
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. Your job is to research a topic thoroughly.
        Follow these steps:
        1. Search the web for the given topic using multiple relevant queries.
        2. Take notes on the key findings from each search using the SaveNote tool.
        3. After gathering enough information, retrieve your notes using GetNotes.
        4. Produce a well-structured final summary based on your notes.
        Be thorough but concise. Use at least 2-3 different search queries to cover different angles.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools
);

// Configure run options
var runOptions = new ChatClientAgentRunOptions(
    new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    }
);

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Please research the following topic and provide a comprehensive summary: {topic}"),
};

Console.WriteLine($"\nResearching: {topic}\n");
Console.WriteLine(new string('=', 60));

try
{
    int stepCount = 0;
    await foreach (var update in agent.RunStreamingAsync(messages, session: null, runOptions))
    {
        stepCount++;
        var role = update.Role?.ToString() ?? "unknown";
        var textLength = update.Text?.Length ?? 0;
        Console.Error.WriteLine($"[Step {stepCount}] Role: {role}, Content length: {textLength}");

        if (!string.IsNullOrEmpty(update.Text))
        {
            Console.Write(update.Text);
        }
    }

    Console.WriteLine();
    Console.WriteLine(new string('=', 60));
}
catch (Exception ex)
{
    Console.Error.WriteLine($"\nError during agent invocation: {ex.Message}");
    Console.Error.WriteLine($"Exception type: {ex.GetType().Name}");
}

// Print all saved notes
Console.WriteLine("\n--- Saved Research Notes ---");
Console.WriteLine(noteTaker.GetNotes());

// --- Tool Classes ---

file class WebSearchTool
{
    [Description("Searches the web for a given query and returns result snippets. Use this to find information about any topic.")]
    public static async Task<string> SearchWebAsync(
        [Description("The search query string")] string query)
    {
        try
        {
            using var httpClient = new HttpClient();
            httpClient.DefaultRequestHeaders.Add("User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
            httpClient.Timeout = TimeSpan.FromSeconds(15);

            var url = $"https://lite.duckduckgo.com/lite?q={Uri.EscapeDataString(query)}";
            var html = await httpClient.GetStringAsync(url);

            // Parse snippets from DuckDuckGo Lite HTML
            var results = ParseDuckDuckGoResults(html);

            if (results.Count == 0)
                return $"No results found for: {query}";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: {query}");
            sb.AppendLine();
            foreach (var (title, snippet) in results.Take(5))
            {
                sb.AppendLine($"• {title}");
                if (!string.IsNullOrEmpty(snippet))
                    sb.AppendLine($"  {snippet}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    private static List<(string Title, string Snippet)> ParseDuckDuckGoResults(string html)
    {
        var results = new List<(string Title, string Snippet)>();

        // DuckDuckGo Lite returns results in table rows with class "result-link" for titles
        // and class "result-snippet" for snippets
        var linkPattern = new Regex(@"class=""result-link""[^>]*>([^<]+)</a>", RegexOptions.IgnoreCase);
        var snippetPattern = new Regex(@"class=""result-snippet""[^>]*>(.*?)</td>", RegexOptions.IgnoreCase | RegexOptions.Singleline);

        var linkMatches = linkPattern.Matches(html);
        var snippetMatches = snippetPattern.Matches(html);

        for (int i = 0; i < linkMatches.Count; i++)
        {
            var title = WebUtility.HtmlDecode(linkMatches[i].Groups[1].Value).Trim();
            var snippet = i < snippetMatches.Count
                ? WebUtility.HtmlDecode(Regex.Replace(snippetMatches[i].Groups[1].Value, @"<[^>]+>", "")).Trim()
                : "";
            results.Add((title, snippet));
        }

        return results;
    }
}

file class NoteTaker
{
    private readonly Dictionary<string, string> _notes = new();

    [Description("Saves a research note with a title and content. Use this to record key findings from your research.")]
    public string SaveNote(
        [Description("A short descriptive title for the note")] string title,
        [Description("The content/details of the note")] string content)
    {
        _notes[title] = content;
        return $"Note saved: '{title}'";
    }

    [Description("Retrieves all saved research notes as formatted text. Use this to review findings before writing a summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        int index = 1;
        foreach (var (title, content) in _notes)
        {
            sb.AppendLine($"{index}. [{title}]");
            sb.AppendLine($"   {content}");
            sb.AppendLine();
            index++;
        }

        return sb.ToString();
    }
}

