 file class WebSearchTool
 {
     [Description("Searches the web for a given query and returns result snippets. Use this to find information about any topic.")]
     public static async Task<string> SearchWebAsync(
         [Description("The search query string")] string query)
     {
         try
         {
             using var httpClient = new HttpClient();
             httpClient.DefaultRequestHeaders.Add("User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
             httpClient.Timeout = TimeSpan.FromSeconds(15);

             var url = $"https://lite.duckduckgo.com/lite?q={Uri.EscapeDataString(query)}";
             var html = await httpClient.GetStringAsync(url);

             // Parse snippets from DuckDuckGo Lite HTML
             var results = ParseDuckDuckGoResults(html);

             if (results.Count == 0)
                 return $"No results found for: {query}";

             var sb = new StringBuilder();
             sb.AppendLine($"Search results for: {query}");
             sb.AppendLine();
             foreach (var (title, snippet) in results.Take(5))
             {
                 sb.AppendLine($"• {title}");
                 if (!string.IsNullOrEmpty(snippet))
                     sb.AppendLine($"  {snippet}");
                 sb.AppendLine();
             }

             return sb.ToString();
         }
         catch (Exception ex)
         {
             return $"Search failed for '{query}': {ex.Message}";
         }
     }

     private static List<(string Title, string Snippet)> ParseDuckDuckGoResults(string html)
     {
         var results = new List<(string Title, string Snippet)>();

         // DuckDuckGo Lite returns results in table rows with class "result-link" for titles
         // and class "result-snippet" for snippets
         var linkPattern = new Regex(@"class=""result-link""[^>]*>([^<]+)</a>", RegexOptions.IgnoreCase);
         var snippetPattern = new Regex(@"class=""result-snippet""[^>]*>(.*?)</td>", RegexOptions.IgnoreCase | RegexOptions.Singleline);

         var linkMatches = linkPattern.Matches(html);
         var snippetMatches = snippetPattern.Matches(html);

         for (int i = 0; i < linkMatches.Count; i++)
         {
             var title = WebUtility.HtmlDecode(linkMatches[i].Groups[1].Value).Trim();
             var snippet = i < snippetMatches.Count
                 ? WebUtility.HtmlDecode(Regex.Replace(snippetMatches[i].Groups[1].Value, @"<[^>]+>", "")).Trim()
                 : "";
             results.Add((title, snippet));
         }

         return results;
     }
 }

